55	  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
56	  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
57	  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
58	  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
59	  static constexpr uint16_t kCsrVstart   = 0x008;
60	  static constexpr uint16_t kCsrVxsat    = 0x009;
61	  static constexpr uint16_t kCsrVxrm     = 0x00A;
62	  static constexpr uint16_t kCsrVcsr     = 0x00F;
63	  static constexpr uint16_t kCsrVtype    = 0xC21;
64	  static constexpr uint16_t kCsrVl       = 0xC20;
65	
66	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
67	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
68	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
69	
70	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
71	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
72	
73	  static constexpr uint32_t kAbstractcsBusy       = hybrid::kAbstractcsBusy;
74	  static constexpr uint32_t kAbstractcsCmderrMask = hybrid::kAbstractcsCmderrMask;
75	
76	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
77	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
78	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
79	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
80	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
81	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
82	
83	  static constexpr unsigned kPollIterations = kDmiPollIterations;
84	
85	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
86	  // v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
87	  // "unset" sentinel; a non-V resume never reads it. The simulator passes the
88	  // real value from platform.main_memory.
89	  explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
90	                        AndesCaps caps = AndesCaps::all())
91	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
92	  {}
93	
94	  // LG1 (liveness gate): supply the engine's own reset-state drain. A tolerant
95	  // CSR write whose drained value equals this baseline is skipped -- the write
96	  // would be a no-op, and every DM operation costs hundreds of simulated
97	  // cycles. Unset (default) keeps transport-everything. Always-live state
98	  // (mstatus, GPRs, dpc, dcsr, mcycle, minstret, the S/U PMP mirror) is never
99	  // gated.
100	  void set_reset_baseline(const hybrid_state_v1& b)
101	  {
102	    baseline_ = b;
103	    has_baseline_ = true;
104	  }
105	
106	  // Number of tolerant CSR writes elided by the reset baseline this resume.
107	  auto baseline_skip_count() const -> uint64_t { return baseline_skip_count_; }
108	
109	  void resume(const hybrid_state_v1& state)
110	  {
111	    if (state.magic != HYBRID_STATE_MAGIC)
112	      throw std::runtime_error("ResumeDriver::resume: bad magic");
113	    if (state.version != HYBRID_STATE_VERSION)
114	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
115	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
116	    if (state.priv == 2 || state.priv > 3)
117	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
118	
119	    // dmactive must transition 0->1 in its own write before any other
120	    // DMCONTROL bit is honored (RISC-V Debug Spec).
121	    bus_.write(kDmcontrol, kDmcontrolDmactive);
122	    request_halt();
123	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
124	
125	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
126	    // accepted (FS or VS == Off disables the extension and the hart NACKs
127	    // the writes). The drained state.mstatus may legitimately carry FS or
128	    // VS at Off (e.g. an OS context-switched the regs away before the
129	    // trigger fired) -- gating the write on the drained field skips the
130	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
131	    // write mstatus when either extension is in scope; force-OR Initial
132	    // when the drained field is Off. This enable is local to the vsim
133	    // phase; the state.mstatus written to the handoff file is left
134	    // unmodified.
135	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
136	      uint64_t enable_mstatus = state.mstatus;
137	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
138	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
139	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
140	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
141	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
142	    }
143	
144	    // FPR restore (requires mstatus.FS enabled above): one abstract register
145	    // write per f-reg. Abstract-only by design, like every non-V register
146	    // block -- the Program Buffer is reserved for state the abstract command
147	    // space cannot reach (the V regfile, vtype/vl, L2C MMIO).
148	    if (state.flags & HYBRID_FLAG_FP) {
149	      for (uint16_t i = 0; i < 32; ++i)
150	        write_64bit_register(regno_fpr(i), state.fpr[i]);
151	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
152	      // fallback scratch x5 is overwritten by the GPR loop below.
153	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
154	    }
155	
156	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
157	    // the GPR loop overwrites x5 afterward so state is preserved).
158	    if (state.flags & HYBRID_FLAG_V) {
159	      // V data regfile: reload v0..v31 from the shared scratch region via the
160	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
161	      // because the sweep's own vsetvl (e8/m8) clobbers vtype/vl/vstart, which
162	      // the restore then overwrites with the architectural values. The sweep
163	      // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
164	      // below restores all three. The scratch is vlenb-packed
165	      // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
166	      if (scratch_gpa_ == kVScratchGpaUnset)
167	        throw std::runtime_error(
168	          "ResumeDriver::resume: V state present but scratch GPA unset");
169	      pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
170	
171	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
172	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
173	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
174	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
175	      write_64bit_register(regno_gpr(5), state.vl);
176	      write_64bit_register(regno_gpr(6), state.vtype);
177	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
178	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
179	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
180	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
181	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
182	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
183	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
184	    }
185	
186	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
187	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
188	    // in the drained privilege; M-mode states skip the write (prv already 3).
189	    // Before the GPR loop: a PB fallback would clobber scratch x5.
190	    if (state.priv != 3) {
191	      // L2 slice: with PMP implemented and no matching entry, every S/U
192	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
193	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
194	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
195	      // RV64. Tolerant writes: entries beyond what the hart implements
196	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
197	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
198	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
199	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
200	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
201	
202	      const uint64_t dcsr =
203	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
204	      write_csr_abstract_or_pb(kCsrDcsr,
205	                               (dcsr & ~uint64_t{0x3}) | state.priv);
206	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
207	      // silently measure the ROI in the wrong privilege. Verify and abort.
208	      const uint64_t got =
209	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
210	        & 0x3u;
211	      if (got != state.priv)
212	        throw std::runtime_error(
213	          "ResumeDriver::resume: engine does not implement privilege level "
214	          + std::to_string(state.priv)
215	          + " (dcsr.prv pinned to " + std::to_string(got)
216	          + "); pick an S/U-capable engine");
217	    }
218	
219	    // Andes V5 + M-ext CSR restore (abstract-only, LG1-gated). See
220	    // restore_andes_m_ext.
221	    restore_andes_m_ext(state);
222	
223	    // GPRs x1..x31 + DPC (after the V CSRs so the PB scratch GPRs the V block
224	    // staged -- x5/x6/x7 -- are safe to overwrite): one abstract register
225	    // write each (DATA0/DATA1 + Access-Register COMMAND), abstract-only by
226	    // design. x0 is hardwired zero and is skipped.
227	    for (uint16_t i = 1; i < 32; ++i)
228	      write_64bit_register(regno_gpr(i), state.gpr[i]);
229	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
230	
231	    write_csr_tolerant_gated(kCsrMtvec, state.mtvec, baseline_.mtvec);
232	
233	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
234	    // register with no hardware side effects, legal to use inside a trap-free
235	    // ROI. Restore it so a value stashed before the handoff survives into the
236	    // vsim phase.
237	    write_csr_tolerant_gated(kCsrMscratch, state.mscratch, baseline_.mscratch);
238	
239	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
240	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
241	    // value stashed before the handoff must survive into the vsim phase (same
242	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
243	    // hardware-driven pending bits, or mtval on a core that hardwires it)
244	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
245	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
246	    write_csr_tolerant_gated(kCsrMepc,   state.mepc,   baseline_.mepc);
247	    write_csr_tolerant_gated(kCsrMcause, state.mcause, baseline_.mcause);
248	    write_csr_tolerant_gated(kCsrMtval,  state.mtval,  baseline_.mtval);
249	    write_csr_tolerant_gated(kCsrMie,    state.mie,    baseline_.mie);
250	    write_csr_tolerant_gated(kCsrMip,    state.mip,    baseline_.mip);
251	
252	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
253	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
254	    // caches) but has no cache model, so without this the cycle engine resumes
255	    // at the ROI with caches at their reset default -- DISABLED -- and the
256	    // whole measured window runs uncached, inflating it severalfold. Tolerant
257	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
258	    // write as a no-op, and a drained 0 (caches were off) restores the reset
259	    // state, so this is always safe to issue.
260	    write_csr_tolerant_gated(kCsrMcacheCtl, state.mcache_ctl,
261	                             baseline_.mcache_ctl);
262	    write_csr_tolerant_gated(kCsrMmiscCtl,  state.mmisc_ctl,
263	                             baseline_.mmisc_ctl);
264	
265	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
266	    // from QEMU1's drain value. Without this, vsim's local counter starts
267	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
268	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
269	    // overwrite here as the GPR loop already ran.
270	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
271	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
272	
273	    clear_cmderr_if_set();
274	    request_resume();
275	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
276	                   "ResumeDriver resume");
277	  }
278	
279	private:
280	  void request_halt()
281	  {
282	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
283	  }
284	
285	  void request_resume()
286	  {
287	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
288	  }
289	
290	  void write_64bit_register(uint16_t regno, uint64_t value)
291	  {
292	    write_register_abstract(bus_, regno, value);
293	  }
294	
295	  // Andes V5 + M-ext CSR restore: one caps-gated abstract write per CSR -- the
296	  // 13 Andes scalars via the HYBRID_ANDES_CSR_LIST X-macro, then PMA
297	  // (pmaaddr0..15 before the even pmacfg, mirroring the PMP restore ordering).
298	  // Abstract-only by design: a batched Program-Buffer sweep can't tolerate a
299	  // cmderr on one CSR without corrupting the rest of the batch (a WARL/read-
300	  // only CSR faults the whole group), whereas the per-CSR abstract path clears
301	  // the error and moves on. Caps-gated: a CSR the target core lacks
302	  // (caps_.supports_csr false) is skipped, so an abstract write to an
303	  // unimplemented CSR can't hang the DM handshake (the ucode/mecc_code cases).
304	  // LG1-gated too (write_csr_tolerant_gated skips a CSR whose drained value
305	  // already equals the engine reset value); the write-mask gating wraps these
306	  // writes at its later commit.
307	  void restore_andes_m_ext(const hybrid_state_v1& state)
308	  {
309	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
310	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
311	    if (!andes && !mext) return;
312	
313	    if (andes) {
314	#define X(field, addr, name)                                                  \
315	    if (caps_.supports_csr(addr))                                             \
316	      write_csr_tolerant_gated(addr, state.andes.field, baseline_.andes.field);
317	      HYBRID_ANDES_CSR_LIST(X)
318	#undef X
319	      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
320	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
321	          write_csr_tolerant_gated(HYBRID_PMA_ADDR0_CSR + i,
322	                                   state.andes.pmaaddr[i],
323	                                   baseline_.andes.pmaaddr[i]);
324	      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
325	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
326	          write_csr_tolerant_gated(HYBRID_PMA_CFG0_CSR + 2 * i,
327	                                   state.andes.pmacfg[i],
328	                                   baseline_.andes.pmacfg[i]);
329	    }
330	    if (mext) {
331	#define X(field, addr, name)                                                  \
332	    if (caps_.supports_csr(addr))                                             \
333	      write_csr_tolerant_gated(addr, state.m_ext.field, baseline_.m_ext.field);
334	      HYBRID_M_EXT_CSR_LIST(X)
335	#undef X
336	    }
337	  }
338	
339	  // Abstract-first CSR write with Program Buffer fallback.
340	  // Tries an abstract register write; if the DM signals cmderr, clears it,
341	  // stages the value in scratch_gpr via abstract GPR write, then executes a
342	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
343	  // to x5 (t0) which the GPR restore loop overwrites later.
344	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
345	                                 uint8_t scratch_gpr = 5)
346	  {
347	    write_64bit_register(regno_csr(csr), value);
348	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
349	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
350	    write_64bit_register(regno_gpr(scratch_gpr), value);
351	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
352	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
353	  }
354	
355	  // Write a CSR-addressable register and clear any cmderr the DM raised.
356	  // Used for CSRs whose abstract-access support may be implementation
357	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
358	  // remaining writes.
359	  void write_csr_tolerant(uint16_t csr, uint64_t value)
360	  {
361	    write_64bit_register(regno_csr(csr), value);
362	    clear_cmderr_if_set();
363	  }
364	
365	  // LG1: true (and counted) when the reset baseline marks this write a no-op.
366	  auto baseline_skips(uint64_t value, uint64_t reset_value) -> bool
367	  {
368	    if (!has_baseline_ || value != reset_value) return false;
369	    ++baseline_skip_count_;
370	    return true;
371	  }
372	
373	  // Tolerant CSR write elided when the value already equals the engine's
374	  // reset value (reset_value is only meaningful when the baseline is set;
375	  // baseline_ is zero-initialized otherwise and baseline_skips ignores it).
376	  void write_csr_tolerant_gated(uint16_t csr, uint64_t value,
377	                                uint64_t reset_value)
378	  {
379	    if (baseline_skips(value, reset_value)) return;
380	    write_csr_tolerant(csr, value);
381	  }
382	
383	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
384	  // is rejected until the bits are W1C-cleared. We tolerate per-register
385	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
386	  // error before resuming so the hart isn't left in a stuck state.
387	  // B17: record the last observed non-zero cmderr and a clear count so a
388	  // partially-broken restore is observable via the public accessors
389	  // instead of silently swallowed.
390	  void clear_cmderr_if_set()
391	  {
392	    const auto status = bus_.read(kAbstractcs);
393	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
394	    if (code != 0u) {
395	      last_observed_cmderr_ = code;
396	      ++cmderr_clear_count_;
397	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
398	    }
399	  }
400	
401	  DmiBus& bus_;
402	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
403	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
404	  hybrid_state_v1 baseline_{};                // LG1: engine reset-state drain
405	  bool has_baseline_ = false;                 // baseline_ valid only when set
406	  uint64_t baseline_skip_count_ = 0;          // LG1: elided tolerant writes
407	  uint32_t last_observed_cmderr_ = 0;
408	  uint64_t cmderr_clear_count_   = 0;
409	
410	public:
411	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
412	  // at least one abstract write tripped a sticky cmderr the restore
413	  // tolerated by clearing. cmderr_clear_count() is the total number of
414	  // such clears across all calls into clear_cmderr_if_set() this run.
415	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
416	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
417	};
418	
419	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
420	// via an Abstract Command. Halts-and-reads contract: caller must have the
421	// hart in the halted state. Shared with StateDrain (drain at exit). If
422	// abstractcs.cmderr goes sticky after the command, the helper clears it and
423	// reports nullopt rather than blocking the caller -- a missing CSR mirrors as
424	// absent instead of corrupting the adjacent field.
425	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
426	                                     const char* poll_label
427	                                       = "read_register_64")
428	  -> std::optional<uint64_t>
429	{
430	  using RD = ResumeDriver;
431	  bus.write(RD::kCommand,
432	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
433	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
434	  const auto status = bus.read(RD::kAbstractcs);
435	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
436	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
437	    return std::nullopt;
438	  }
439	  const uint64_t lo = bus.read(RD::kData0);
440	  const uint64_t hi = bus.read(RD::kData1);
441	  return lo | (hi << 32);
442	}
443	
444	inline auto read_register_64(DmiBus& bus, uint16_t regno,
445	                             const char* poll_label = "read_register_64")
446	  -> uint64_t
447	{
448	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
449	}
450	
451	}  // namespace hybrid
