221	  {
222	    hybrid::CsrTrigger trigger;
223	    if (exit_pc) {
224	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
225	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
226	    } else {
227	      auto elf = LIEF::ELF::Parser::parse(elf_path);
228	      if (!elf)
229	        throw std::runtime_error(
230	          "enable_hybrid_handoff: failed to parse " + elf_path);
231	      for (const auto& seg: elf->segments()) {
232	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
233	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
234	        const auto content = seg.content();
235	        const std::span<const uint8_t> bytes{content.data(), content.size()};
236	        trigger.scan_buffer(bytes, seg.virtual_address());
237	      }
238	    }
239	
240	    hybrid_dmi_bus_ = std::make_unique<
241	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
242	                            PLATFORM::dmi_data_width>>(platform.dmi,
243	                                                       platform.clk.period());
244	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_);
245	    if (hybrid_input_state_)
246	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
247	    hybrid_handoff_->set_minimal_drain(drain_minimal);
248	    hybrid_state_path_ = state_out_path;
249	  }
250	
251	  void restore_context(const std::string& dir)
252	  {
253	    context_config.dir = dir;
254	    context_config.restore(platform, cpu);
255	  }
256	
257	  void save_context(const std::string& dir)
258	  {
259	    context_config.dir = dir;
260	    context_config.save(platform, cpu);
261	  }
262	
263	  // skip_memory_load: parse the ELF and set the reset vector, but leave
264	  // platform.main_memory untouched. Used in tier-2 hybrid resume where
265	  // QEMU 1's -kernel already populated the shared mmap; re-loading would
266	  // zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
267	  // to static buffers. The reset vector is still set so the hart has a
268	  // valid fetch target during the post-reset cycles that precede the DMI
269	  // halt+DPC-write resume sequence.
270	  void load_elf(const std::string& path, bool skip_memory_load = false)
271	  {
272	    const auto elf = LIEF::ELF::Parser::parse(path);
273	    if (!elf) {
274	      spdlog::critical("Check if it's a valid ELF file path : {}", path);
275	      exit(1);
276	    }
277	
278	    if (!skip_memory_load)
279	      read_elf_into_memory(
280	        *elf,
281	        static_cast<xlen_t>(platform.main_memory.region.base_address),
282	        platform.main_memory.data);
283	    for (auto& rv: platform.reset_vector)
284	      rv.write(elf->entrypoint());
285	  }
286	
287	  void set_reset_vector(size_t hart, uint64_t addr)
288	  {
289	    if (hart >= platform.reset_vector.size()) {
290	      spdlog::critical("hart {} out of range (max {})", hart,
291	                       platform.reset_vector.size() - 1);
292	      std::exit(EXIT_FAILURE);
293	    }
294	    platform.reset_vector[hart].write(addr);
295	  }
296	
297	  void load_image(const std::string& path, MEM_TYPE type)
298	  {
299	    switch (type) {
300	    case MEM_TYPE::ILM:
301	      if constexpr (requires { cpu.set_ilm({}); }) {
302	        read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
303	      } else {
304	        throw std::runtime_error(
305	          "CPU does not support ILM - cannot load ILM ROM image");
306	      }
307	      break;
308	
309	    case MEM_TYPE::DLM:
310	      if constexpr (requires { cpu.set_dlm({}); }) {
311	        read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
312	      } else {
313	        throw std::runtime_error(
314	          "CPU does not support DLM - cannot load DLM ROM image");
315	      }
316	      break;
317	
318	    case MEM_TYPE::RAM:
319	      read_binary_file(path, [this](const auto& data) {
320	        if (data.size() > platform.main_memory.data.size())
321	          throw std::runtime_error("RAM image size exceeds main memory size");
322	        std::copy(data.begin(), data.end(), platform.main_memory.data.begin());
323	      });
324	      break;
325	
326	    default:
327	      throw std::runtime_error("Unknown memory type");
328	    }
329	  }
330	
331	  void reset()
332	  {
333	    static constexpr int core_num = CPU::NDS_NHART;
334	    static constexpr int reset_val = (1 << core_num) - 1;
335	
336	    platform.resetn.write(0);
337	    auto saved = context_config;
338	    context_config = {};
339	    this->run(1);
340	    context_config = saved;
341	
342	    for (size_t i = 0; i < platform.reset_vector.size(); ++i)
343	      spdlog::info("hart {} reset vector: {:#x}", i,
344	                   (uint64_t) platform.reset_vector[i].read());
345	
346	    platform.resetn.write(reset_val);
347	
348	    if (context_config.continue_from)
349	      restore_context(context_config.dir);
350	  }
351	
352	  int run(const uint64_t max_cycles = std::numeric_limits<uint64_t>::max())
353	  {
354	    auto sa = memzeroed<struct sigaction>();
355	    sa.sa_handler = sigint_handler;
356	    sigemptyset(&sa.sa_mask);
357	
358	    auto oact = memzeroed<struct sigaction>();
359	    if (sigaction(SIGINT, &sa, &oact) == -1)
360	      perror("sigaction");
361	
362	    const auto restore_sigint = std::experimental::scope_exit{[&] {
363	      if (sigaction(SIGINT, &oact, nullptr) == -1)
364	        perror("sigaction");
365	    }};
366	
367	    // wait for debugger connections
368	    while (dtm_debug && !dtm.is_connected()) {
369	      dtm.try_accept_socket();
370	      if (ctrlc != 0) {
371	        return 130;
372	      }
373	      sleep(1);
374	    }
375	
376	    [[maybe_unused]]
377	    bool ctx_resuming = context_config.continue_from;
378	    [[maybe_unused]]
379	    bool ctx_triggered = false;
380	
381	    for (auto n = uint64_t{0}; n < max_cycles; ++n) {
382	
383	      if (ctx_resuming) [[unlikely]] {
384	        // Pull up PLIC interrupt signal at the first cycle of the resume
385	        platform.int_trigger.write(1);
386	        ctx_resuming = false;
387	        ctx_triggered = true;
388	      }
389	
390	      sc_core::sc_start(platform.clk.period());
391	
392	      trace_.on_cycle(cpu);
393	
394	      if (hybrid_handoff_) [[unlikely]] {
395	        if (auto code = check_hybrid_handoff(); code) return *code;
396	      }
397	
398	      if (context_config.save_on_wfi && platform.wfi_signal.read() == true)
399	        [[unlikely]]
400	      {
401	        context_config.save(platform, cpu);
402	        spdlog::info("User save context");
403	        return 0;
404	      }
405	
406	      if (ctrlc != 0) {
407	        ctrlc = 0;
408	        spdlog::info("Ctrl+C PC: {:x}", get_current_pc());
409	        trace_.log_committed_pcs(cpu);
410	        return 130;
411	      }
412	
413	      if (ctx_triggered) [[unlikely]] {
414	        // Pull down the interrupt signal after 1 cycle
415	        platform.int_trigger.write(0);
416	        ctx_triggered = false;
417	      }
418	
419	      if (platform.sim_control.exits >= 0) {
420	        spdlog::info("sim_control: got exit {}, stopping",
421	                     platform.sim_control.exits);
422	        spdlog::info("Exit PC: {:x}", get_current_pc());
423	        trace_.log_committed_pcs(cpu);
424	        return platform.sim_control.exits;
425	      }
426	
427	      if (this->cpu.contextp()->gotFinish())
428	        return 0;
429	
430	      spdlog::trace("PC: {:x}", get_current_pc());
431	    }
432	    return 0;
433	  }
434	
435	  uint64_t get_current_pc()
436	  {
437	    if constexpr (requires { cpu.get_current_pc(); }) {
438	      return cpu.get_current_pc();
439	    }
440	    return std::numeric_limits<uint64_t>::max();
441	  }
442	
443	  auto check_hybrid_handoff() -> std::optional<int>
444	  {
445	    if constexpr (!requires { cpu.get_committed_pc(); }) {
446	      return std::nullopt;
447	    } else {
448	      const auto committed = cpu.get_committed_pc();
449	      if (committed.empty()) return std::nullopt;
450	      for (const auto pc: committed[0]) {
451	        auto state = hybrid_handoff_->on_retire(pc);
452	        if (state) {
453	          spdlog::info("hybrid handoff: drained at pc=0x{:x}, writing {}",
454	                       pc, hybrid_state_path_);
455	          std::ofstream f(hybrid_state_path_, std::ios::binary);
456	          f.write(reinterpret_cast<const char*>(&*state), sizeof(*state));
457	          return hybrid::kExitHandoffToQemu;
458	        }
459	      }
460	      return std::nullopt;
461	    }
462	  }
